-- 21 September 2026 desk. Every brief is based on its original official release.
insert into public.current_affairs_briefs (slug, published_on, title, summary, why_it_matters, background, source_title, source_url, source_publisher, source_published_on, prelims_takeaways, quick_check, visual_data, status, reviewed_at) values
(
$$2026-09-21-core-industries-august$$,$$2026-09-21$$,$$August core-sector output grows 4.8% on the new 2022–23 base$$,
$$The Index of Core Industries grew 4.8% year on year in August 2026. Cement and electricity led growth, while coal, natural gas, crude oil and fertilisers contracted.$$,
$$ICI is an early physical-output indicator for key inputs, not a measure of prices, company profit or GDP. The release also distinguishes August's provisional estimate from July's final estimate.$$,
$$The revised ICI series uses 2022–23 as its base year and covers nine infrastructure-linked industries: coal, crude oil, natural gas, refinery products, fertilisers, steel, cement, electricity and iron ore.$$,
$$Provisional Estimates of Index of Core Industries for August 2026$$,$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313043&lang=1&reg=6$$,$$Ministry of Commerce and Industry / Press Information Bureau$$,$$2026-09-21$$,
$$["The ICI base year is 2022–23.","It grew 4.8% year on year in August 2026.","Cement (12.5%) and electricity (11.6%) recorded the fastest listed growth.","The April–August cumulative ICI growth was 4.3% on a provisional basis."]$$::jsonb,
$$[{"question":"How many industries are covered by the ICI?","answer":"Nine."},{"question":"Is an ICI value a price index?","answer":"No. It tracks production in core industries."}]$$::jsonb,
$${"title":"Reading ICI","steps":["Collect output data for nine core industries.","Compare with the same month a year earlier.","Publish a provisional estimate.","Revise it when final information is available."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-national-formulary-biovigilance$$,$$2026-09-21$$,$$National Formulary 2026 and Biovigilance Programme expand patient-safety tools$$,
$$The Indian Pharmacopoeia Commission released the seventh National Formulary of India and will lead the newly approved Biovigilance Programme of India for transplant-related medicines and biological products.$$,
$$This is a public-health regulation update. A formulary guides rational prescribing; pharmacovigilance, materiovigilance and biovigilance monitor different categories of safety risk.$$,
$$IPC coordinates the Pharmacovigilance Programme of India. The 2026 formulary has 34 chapters, 20 appendices and 653 drugs, and is also available through NFI Online.$$,
$$7th National Formulary of India 2026 and Biovigilance Programme$$,$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2312930&lang=1&reg=3$$,$$Ministry of Health and Family Welfare / Press Information Bureau$$,$$2026-09-21$$,
$$["IPC published the NFI periodically since 2009.","NFI 2026 is its seventh edition and covers 653 drugs.","Biovigilance will monitor adverse events linked to organ and tissue transplantation.","PvPI covers adverse drug reactions, while MvPI concerns medical devices."]$$::jsonb,
$$[{"question":"Which body leads the Biovigilance Programme of India?","answer":"The Indian Pharmacopoeia Commission."},{"question":"What does materiovigilance monitor?","answer":"Adverse events associated with medical devices."}]$$::jsonb,
$${"title":"Patient-safety surveillance","steps":["Health products or transplant procedures are used.","An adverse event is reported.","The relevant vigilance programme assesses the signal.","Evidence supports safer guidance and prevention."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-pmsetu-kurukshetra-iti-cluster$$,$$2026-09-21$$,$$PM-SETU approves ₹320 crore for the Kurukshetra ITI hub-and-spoke cluster$$,
$$The National Steering Committee approved a ₹320 crore Strategic Investment Plan under PM-SETU for one Hub ITI and six Spoke ITIs in Haryana's Kurukshetra cluster.$$,
$$The approval is a skilling-policy development. It is an approved investment plan, not evidence that every proposed laboratory, course or placement outcome is already in operation.$$,
$$PM-SETU aims to upgrade 1,000 Government ITIs through 200 Hub and 800 Spoke ITIs. Jindal Naveen Avsar Limited is the anchor industry partner for this cluster.$$,
$$NSC Approves ₹320 Crore under PM-SETU for Kurukshetra ITI Cluster$$,$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2312980&lang=1&reg=3$$,$$Ministry of Skill Development and Entrepreneurship / Press Information Bureau$$,$$2026-09-21$$,
$$["PM-SETU stands for Pradhan Mantri Skilling and Employability Transformation through Upgraded ITIs.","The Kurukshetra plan covers seven Government ITIs in a Hub-and-Spoke structure.","Government ITI Kurukshetra is the Hub ITI.","PM-SETU has a total outlay of ₹60,000 crore."]$$::jsonb,
$$[{"question":"How many Spoke ITIs does the Kurukshetra cluster have?","answer":"Six."},{"question":"What is the intended role of an anchor industry partner?","answer":"To support industry-aligned training, apprenticeships and employment linkages."}]$$::jsonb,
$${"title":"PM-SETU cluster model","steps":["A Hub ITI coordinates a cluster.","Spoke ITIs receive upgraded facilities and courses.","Industry partners shape practical training.","Apprenticeships and placement links strengthen employability."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-nomadic-elephant-2026$$,$$2026-09-21$$,$$India–Mongolia Exercise Nomadic Elephant begins at Pithoragarh$$,
$$The 18th India–Mongolia joint military exercise, Nomadic Elephant, began at the Foreign Training Node, Pithoragarh, Uttarakhand, and is scheduled through 3 October.$$,
$$Joint exercises test bilateral defence cooperation and military vocabulary. The stated objective is interoperability for counter-insurgency operations in semi-urban and mountainous terrain under a UN mandate.$$,
$$Nomadic Elephant is an annual platoon-level exercise held alternately in India and Mongolia. Each side is represented by 45 personnel in the 2026 edition.$$,
$$India–Mongolia Joint Military Exercise Nomadic Elephant Commences at Pithoragarh$$,$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313046&lang=1&reg=6$$,$$Ministry of Defence / Press Information Bureau$$,$$2026-09-21$$,
$$["Nomadic Elephant is a bilateral India–Mongolia exercise.","The 2026 edition is the 18th.","It is conducted alternately in the two countries.","The 2026 venue is Pithoragarh, Uttarakhand."]$$::jsonb,
$$[{"question":"Which country partners India in Exercise Nomadic Elephant?","answer":"Mongolia."},{"question":"What kind of exercise is it?","answer":"An annual platoon-level joint military exercise."}]$$::jsonb,
$${"title":"Bilateral exercise purpose","steps":["Partner forces assemble for joint training.","They practise agreed operational drills.","Interoperability and shared procedures improve.","The exercise supports wider defence cooperation."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-t72-t90-auxiliary-power-units$$,$$2026-09-21$$,$$Indigenous auxiliary power units contracted for T-72 and T-90 tanks$$,
$$The Defence Ministry signed a ₹586 crore contract with Accurate Industrial Controls Private Limited to procure auxiliary power units for the Army's T-72 and T-90 tanks.$$,
$$An APU is a separate electrical-power source for systems such as fire control and gun stabilisation; it is not the tank's main engine. The procurement is a contract, not a statement that all units have already been inducted.$$,
$$The Ministry describes the project as industry-led research and development under Make-II, linking it to indigenous critical subsystems for armoured platforms.$$,
$$MoD inks ₹586 crore contract to procure Auxiliary Power Units for T-72 and T-90 Tanks$$,$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313016&lang=2&reg=48$$,$$Ministry of Defence / Press Information Bureau$$,$$2026-09-21$$,
$$["The contract value is ₹586 crore.","It covers APUs for T-72 and T-90 tanks.","APUs can power fire-control, firing-circuit and gun-stabilisation systems.","The project is under the Make-II category."]$$::jsonb,
$$[{"question":"Is an APU the main engine of a tank?","answer":"No. It is an alternate electrical-power source for onboard systems."},{"question":"Which procurement category is cited for this project?","answer":"Make-II."}]$$::jsonb,
$${"title":"From indigenous design to armour readiness","steps":["Industry develops a subsystem under Make-II.","The Ministry places a procurement contract.","APUs supply electrical power to key tank systems.","Induction can improve readiness and sustainability."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-telecom-identifier-safety$$,$$2026-09-21$$,$$DoT applies Telecommunications Act safeguards to fraudulent SIM and IMEI misuse$$,
$$The Department of Telecommunications highlighted action after a point-of-sale agent allegedly activated 25 SIMs using citizens' identity documents without consent, and reiterated the legal consequences of identifier misuse.$$,
$$This connects cyber safety with telecom law. The release is an enforcement and public-safety update, not a new amendment to the Telecommunications Act, 2023.$$,
$$DoT states that fraudulent SIM issuance, misuse of telecom identifiers and IMEI tampering can attract imprisonment up to three years and a fine up to ₹50 lakh. Its Digital Intelligence Platform was used to examine the suspect numbers.$$,
$$DoT cautions citizens against fraudulent SIM issuance, telecom-identifier misuse and IMEI tampering$$,$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2312868&lang=1&reg=3$$,$$Ministry of Communications / Press Information Bureau$$,$$2026-09-21$$,
$$["IMEI is a telecommunication identifier for a mobile device.","The cited legal framework is the Telecommunications Act, 2023.","The stated maximum penalty is three years' imprisonment and ₹50 lakh fine.","Sanchar Saathi provides citizen-facing services for checking and securing connections and handsets."]$$::jsonb,
$$[{"question":"Which portal does DoT direct citizens to use for telecom-safety services?","answer":"Sanchar Saathi."},{"question":"Does this release enact a new telecom law?","answer":"No. It reiterates enforcement under the Telecommunications Act, 2023."}]$$::jsonb,
$${"title":"Telecom-identifier protection","steps":["A subscriber or device identifier is issued.","Misuse is detected through investigation or intelligence tools.","Suspicious connections are re-verified or deactivated.","The Act supplies offences and penalties."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-avyay-senior-support$$,$$2026-09-21$$,$$AVYAY update tracks assistive devices, Elderline and geriatric-care training$$,
$$The Social Justice Ministry reported more than 46.32 lakh assistive devices for over 8.53 lakh senior citizens under Rashtriya Vayoshri Yojana, more than 29 lakh Elderline calls, and 35,480 trained geriatric caregivers.$$,
$$The exam value is the architecture of senior-citizen support: AVYAY is the umbrella scheme, while RVY, Elderline and caregiver training are distinct components or services.$$,
$$RVY is implemented through ALIMCO for eligible older persons with age-related disabilities. Elderline is the national helpline for senior citizens, reachable on 14567.$$,
$$Assistive Devices, Elderline and Trained Caregivers Strengthen Support for Senior Citizens$$,$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2313057&lang=1&reg=3$$,$$Ministry of Social Justice and Empowerment / Press Information Bureau$$,$$2026-09-21$$,
$$["AVYAY is the Atal Vayo Abhyudaya Yojana.","RVY began in 2017 and is implemented through ALIMCO.","Elderline is the National Helpline for Senior Citizens: 14567.","The caregiver-training scheme began in FY 2023–24."]$$::jsonb,
$$[{"question":"What is the Elderline number?","answer":"14567."},{"question":"Which PSU implements Rashtriya Vayoshri Yojana?","answer":"Artificial Limbs Manufacturing Corporation of India, or ALIMCO."}]$$::jsonb,
$${"title":"Senior-support ecosystem","steps":["AVYAY provides an umbrella framework.","RVY supplies assistive devices.","Elderline provides guidance and intervention support.","Caregiver training strengthens longer-term care capacity."]}$$::jsonb,$$published$$,now()
),
(
$$2026-09-21-cbn-brahma-kumaris-yuva-raksha$$,$$2026-09-21$$,$$Central Bureau of Narcotics and Brahma Kumaris create a prevention-outreach framework$$,
$$The Central Bureau of Narcotics and Brahma Kumaris signed an MoU for preventive drug awareness, youth engagement and community outreach under the CBN's Yuva Raksha initiative.$$,
$$The agreement is a prevention and awareness partnership. It does not give volunteers enforcement, investigation or policing powers, which remain statutory functions.$$,
$$CBN is part of the Department of Revenue, Ministry of Finance. The MoU gives special operational emphasis to Madhya Pradesh, Rajasthan, Uttar Pradesh and Delhi.$$,
$$Central Bureau of Narcotics and Brahma Kumaris sign MoU for preventive drug awareness$$,$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313188&lang=2&reg=48$$,$$Ministry of Finance / Press Information Bureau$$,$$2026-09-21$$,
$$["CBN is under the Department of Revenue in the Ministry of Finance.","The MoU relates to the Yuva Raksha preventive-awareness initiative.","Its named focus areas are Madhya Pradesh, Rajasthan, Uttar Pradesh and Delhi.","The non-government partner has no enforcement or policing function under the MoU."]$$::jsonb,
$$[{"question":"Which ministry contains the Central Bureau of Narcotics?","answer":"The Ministry of Finance, through the Department of Revenue."},{"question":"Do Brahma Kumaris volunteers receive policing powers under this MoU?","answer":"No. Their activities are voluntary, educational and non-regulatory."}]$$::jsonb,
$${"title":"Prevention partnership boundary","steps":["CBN brings statutory and preventive-awareness expertise.","A community partner mobilises outreach networks.","Yuva Raksha activities target youth and communities.","Enforcement authority remains with competent agencies."]}$$::jsonb,$$published$$,now()
)
on conflict (slug) do update set title=excluded.title, summary=excluded.summary, why_it_matters=excluded.why_it_matters, background=excluded.background, source_title=excluded.source_title, source_url=excluded.source_url, source_publisher=excluded.source_publisher, source_published_on=excluded.source_published_on, prelims_takeaways=excluded.prelims_takeaways, quick_check=excluded.quick_check, visual_data=excluded.visual_data, status=excluded.status, reviewed_at=excluded.reviewed_at, updated_at=now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in ($$2026-09-21-core-industries-august$$,$$2026-09-21-national-formulary-biovigilance$$,$$2026-09-21-pmsetu-kurukshetra-iti-cluster$$,$$2026-09-21-nomadic-elephant-2026$$,$$2026-09-21-t72-t90-auxiliary-power-units$$,$$2026-09-21-telecom-identifier-safety$$,$$2026-09-21-avyay-senior-support$$,$$2026-09-21-cbn-brahma-kumaris-yuva-raksha$$)
and exams.slug in ($$cuet$$,$$ssc-cgl$$,$$uppsc-ro-aro$$,$$up-secretariat-ro-aro$$) on conflict do nothing;
